export function parseCsv(text: string): string[][] {
  const rows: string[][] = [];
  let row: string[] = [];
  let field = "";
  let inQuotes = false;
  let i = 0;

  const endRow = () => {
    row.push(field);
    const isBlankLine = row.length === 1 && row[0] === "";
    if (!isBlankLine) rows.push(row);
    row = [];
    field = "";
  };

  while (i < text.length) {
    const char = text[i];
    if (inQuotes) {
      if (char === '"' && text[i + 1] === '"') {
        field += '"';
        i += 2;
        continue;
      }
      if (char === '"') inQuotes = false;
      else field += char;
      i++;
      continue;
    }
    if (char === '"') {
      inQuotes = true;
    } else if (char === ",") {
      row.push(field);
      field = "";
    } else if (char === "\n") {
      endRow();
    } else if (char === "\r" && text[i + 1] === "\n") {
      endRow();
      i++;
    } else {
      field += char;
    }
    i++;
  }
  if (field !== "" || row.length > 0) endRow();
  return rows;
}
EOF
cat > src/money.ts <<'EOF'
const AMOUNT = /^(-?)(\d+|\d{1,3}(?:,\d{3})+)(?:\.(\d{1,2}))?$/;

export function parseAmount(raw: string): number {
  const match = AMOUNT.exec(raw);
  if (!match) throw new Error(`invalid amount: ${raw}`);
  const [, sign, integerPart, fraction = ""] = match;
  const cents = Number(integerPart.replaceAll(",", "")) * 100 + Number(fraction.padEnd(2, "0"));
  return sign === "-" && cents !== 0 ? -cents : cents;
}

export function formatCents(cents: number): string {
  const sign = cents < 0 ? "-" : "";
  const absolute = Math.abs(cents);
  const fraction = String(absolute % 100).padStart(2, "0");
  return `${sign}${Math.floor(absolute / 100)}.${fraction}`;
}
EOF
cat > src/report.ts <<'EOF'
import { parseCsv } from "./csv";
import { parseAmount } from "./money";

export type Summary = {
  totals: Map<string, number>;
  skipped: number;
};

const COLUMN_COUNT = 4;

export function summarize(csvText: string): Summary {
  const rows = parseCsv(csvText).slice(1);
  const totals = new Map<string, number>();
  let skipped = 0;
  for (const row of rows) {
    if (row.length !== COLUMN_COUNT) {
      skipped++;
      continue;
    }
    const [, rawCategory, , rawAmount] = row;
    let cents: number;
    try {
      cents = parseAmount(rawAmount);
    } catch {
      skipped++;
      continue;
    }
    const category = rawCategory.trim();
    totals.set(category, (totals.get(category) ?? 0) + cents);
  }
  return { totals, skipped };
}
EOF
